BEGIN;
DO $test$
DECLARE adm uuid; learner uuid; other uuid; cid uuid; comp uuid; bid uuid; mapping uuid; class_a uuid; class_a2 uuid; class_b uuid; response_id uuid; result jsonb; caught boolean; expected_learners integer; expected_classes integer;
BEGIN
 SELECT user_id INTO adm FROM public.admin_users WHERE active LIMIT 1;
 SELECT u.id INTO learner FROM auth.users u WHERE NOT EXISTS(SELECT 1 FROM public.admin_users a WHERE a.user_id=u.id AND a.active) ORDER BY u.id LIMIT 1;
 SELECT id INTO other FROM auth.users WHERE id NOT IN(adm,learner) ORDER BY id LIMIT 1;
 IF adm IS NULL OR learner IS NULL OR other IS NULL THEN RAISE EXCEPTION 'An admin and two users are required for rollback fixtures'; END IF;
 PERFORM set_config('request.jwt.claim.sub',adm::text,true);
 INSERT INTO public.concepts(name,slug,subject) VALUES('Curriculum fixture','curriculum-test-'||gen_random_uuid(),'Mathematics') RETURNING id INTO cid;
 INSERT INTO public.concept_competencies(concept_id,depth,competency_key,description,evidence_type,review_status) VALUES(cid,'foundation','ratio','Interpret a ratio','quick_check','published') RETURNING id INTO comp;
 INSERT INTO public.knowledge_blocks(concept_id,depth,block_type,title,sequence,review_status,content) VALUES(cid,'foundation','quick_check','Ratio fixture',0,'published',
 '{"body":"Compare quantities.","competencyKeys":["ratio"],"quickCheck":{"prompt":"Which compares quantities?","options":["Ratio","Colour"],"correctIndex":0,"explanation":"Ratios compare quantities."}}') RETURNING id INTO bid;
 mapping:=public.admin_save_curriculum_mapping(jsonb_build_object('competency_id',comp,'framework','Fixture','framework_version','2026','grade','Year 7','standard_code','M1','standard_description','Interpret a ratio','source_url','https://example.org/fixture','review_status','draft'));
 INSERT INTO public.classes(teacher_id,name,code) VALUES(adm,'A','TEST-'||gen_random_uuid()) RETURNING id INTO class_a;
 INSERT INTO public.classes(teacher_id,name,code) VALUES(adm,'A2','TEST-'||gen_random_uuid()) RETURNING id INTO class_a2;
 INSERT INTO public.classes(teacher_id,name,code) VALUES(other,'B','TEST-'||gen_random_uuid()) RETURNING id INTO class_b;
 INSERT INTO public.class_students(class_id,student_id,display_name) VALUES(class_a,learner,'A learner'),(class_a2,learner,'Same learner'),(class_b,other,'B learner');
 PERFORM set_config('request.jwt.claim.sub',learner::text,true);
 PERFORM public.answer_block_check(bid,1,0);
 caught:=false; BEGIN PERFORM public.teacher_competency_coverage(class_a); EXCEPTION WHEN OTHERS THEN caught:=true; END;
 IF NOT caught THEN RAISE EXCEPTION 'Learner accessed class analytics'; END IF;
 caught:=false; BEGIN PERFORM public.teacher_competency_coverage(class_b); EXCEPTION WHEN OTHERS THEN caught:=true; END;
 IF NOT caught THEN RAISE EXCEPTION 'Learner accessed another class'; END IF;
 caught:=false; BEGIN PERFORM public.admin_delete_curriculum_mapping(mapping); EXCEPTION WHEN OTHERS THEN caught:=true; END;
 IF NOT caught THEN RAISE EXCEPTION 'Learner removed a mapping'; END IF;
 SET LOCAL ROLE authenticated;
 IF jsonb_array_length(public.concept_curriculum_mappings(cid))<>0 THEN RAISE EXCEPTION 'Draft curriculum mapping leaked'; END IF;
 RESET ROLE;
 PERFORM set_config('request.jwt.claim.sub',adm::text,true);
 SELECT count(DISTINCT cs.student_id) INTO expected_learners FROM public.class_students cs JOIN public.classes cls ON cls.id=cs.class_id WHERE cls.teacher_id=adm;
 SELECT count(*) INTO expected_classes FROM public.classes WHERE teacher_id=adm;
 result:=public.teacher_competency_coverage();
 IF (result->>'learners')::int<>expected_learners OR (result->>'classes')::int<>expected_classes THEN RAISE EXCEPTION 'Duplicate enrollment inflated teacher totals'; END IF;
 result:=public.teacher_competency_coverage(class_a);
 IF (result->>'learners')::int<>1 OR (result->>'classes')::int<>1 THEN RAISE EXCEPTION 'Class filter ignored'; END IF;
 IF NOT EXISTS(SELECT 1 FROM jsonb_array_elements(result->'competencies') row WHERE row->>'id'=comp::text AND (row->>'demonstrated')::int=1) THEN RAISE EXCEPTION 'Valid block proof absent from class summary'; END IF;
 PERFORM set_config('request.jwt.claim.sub',other::text,true);
 result:=public.teacher_competency_coverage(class_b);
 IF EXISTS(SELECT 1 FROM jsonb_array_elements(result->'competencies') row WHERE row->>'id'=comp::text AND (row->>'demonstrated')::int<>0) THEN RAISE EXCEPTION 'Evidence crossed class boundaries'; END IF;
 PERFORM set_config('request.jwt.claim.sub',adm::text,true);
 UPDATE public.competency_curriculum_mappings SET review_status='approved' WHERE id=mapping;
 IF NOT EXISTS(SELECT 1 FROM public.competency_curriculum_mappings WHERE id=mapping AND reviewed_by=adm AND reviewed_at IS NOT NULL) THEN RAISE EXCEPTION 'Curriculum approval attribution missing'; END IF;
 PERFORM set_config('request.jwt.claim.sub',learner::text,true);
 SET LOCAL ROLE authenticated;
 IF jsonb_array_length(public.concept_curriculum_mappings(cid))<>1 THEN RAISE EXCEPTION 'Approved alignment missing for published competency'; END IF;
 RESET ROLE;
 PERFORM public.answer_block_check(bid,1,1);
 PERFORM set_config('request.jwt.claim.sub',adm::text,true);
 result:=public.teacher_competency_coverage(class_a);
 IF EXISTS(SELECT 1 FROM jsonb_array_elements(result->'competencies') row WHERE row->>'id'=comp::text AND (row->>'demonstrated')::int<>0) THEN RAISE EXCEPTION 'Earlier pass hid a later failure'; END IF;
 caught:=false; BEGIN UPDATE public.knowledge_blocks SET content=content||'{"narration":42}' WHERE id=bid; EXCEPTION WHEN OTHERS THEN caught:=true; END;
 IF NOT caught THEN RAISE EXCEPTION 'Non-text narration accepted'; END IF;
 caught:=false; BEGIN UPDATE public.knowledge_blocks SET content=content||'{"visualCaption":"Missing diagram"}' WHERE id=bid; EXCEPTION WHEN OTHERS THEN caught:=true; END;
 IF NOT caught THEN RAISE EXCEPTION 'Orphan diagram guidance accepted'; END IF;
 UPDATE public.knowledge_blocks SET version=2,content='{"body":"Explain a ratio.","competencyKeys":["ratio"],"narration":"Compare two quantities.","task":{"prompt":"Explain how to compare two quantities fairly.","rubric":["Identify both quantities"]}}' WHERE id=bid;
 PERFORM set_config('request.jwt.claim.sub',learner::text,true);
 response_id:=public.submit_block_response(bid,2,'I will identify both quantities and compare them in consistent units.');
 PERFORM set_config('request.jwt.claim.sub',adm::text,true);
 PERFORM public.review_block_response(response_id,true,'Both quantities and units are clear.');
 result:=public.teacher_competency_coverage(class_a);
 IF NOT EXISTS(SELECT 1 FROM jsonb_array_elements(result->'competencies') row WHERE row->>'id'=comp::text AND (row->>'demonstrated')::int=1) THEN RAISE EXCEPTION 'Reviewed current-version task missing from summary'; END IF;
 PERFORM set_config('request.jwt.claim.sub',learner::text,true);
 PERFORM public.submit_block_response(bid,2,'I revised the explanation to state the quantities and their units explicitly.');
 PERFORM set_config('request.jwt.claim.sub',adm::text,true);
 result:=public.teacher_competency_coverage(class_a);
 IF EXISTS(SELECT 1 FROM jsonb_array_elements(result->'competencies') row WHERE row->>'id'=comp::text AND (row->>'demonstrated')::int<>0) THEN RAISE EXCEPTION 'Pending review retained class-level coverage'; END IF;
 RAISE NOTICE 'Curriculum and class analytics assertions passed';
END;
$test$;
ROLLBACK;
